<script setup>
import {ref,computed} from 'vue';
const props=defineProps({roles:Array,groups:Array,archivedRoles:{type:Array,default:()=>[]}});const emit=defineEmits(['action','close']);
const name=ref(''),search=ref('');const filtered=computed(()=>props.roles.filter(r=>(r.name+' '+r.server).includes(search.value.trim())));
function neighbor(role,delta){const rows=props.roles.filter(r=>(r.group_id||'')===(role.group_id||''));return rows[rows.findIndex(r=>r.key===role.key)+delta]}
function moveRole(role,delta){const other=neighbor(role,delta);if(!other)return;const order=props.roles.map(r=>r.key),a=order.indexOf(role.key),b=order.indexOf(other.key);[order[a],order[b]]=[order[b],order[a]];emit('action',{action:'reorder',roles:order})}
function create(){if(name.value.trim()){emit('action',{action:'create',name:name.value});name.value=''}}
</script>
<template><section class="group-editor" aria-label="日常清单角色分组"><div class="editor-head"><div><h2>角色分组</h2><p>仅用于日常清单，分组、角色顺序与折叠状态保存在本地。</p></div><button @click="emit('close')">完成分组</button></div><div class="group-create"><input aria-label="新分组名称" v-model="name" maxlength="30" placeholder="新分组名称" @keydown.enter="create"><button @click="create" :disabled="!name.trim()">新建分组</button><button @click="emit('action',{action:'collapse_all',collapsed:false})">展开全部</button><button @click="emit('action',{action:'collapse_all',collapsed:true})">折叠全部</button></div><div class="group-names"><div v-for="g in groups.filter(g=>g.id)" :key="g.id"><input :aria-label="'重命名分组 '+g.name" :value="g.name" maxlength="30" @change="emit('action',{action:'rename',id:g.id,name:$event.target.value})"><button @click="emit('action',{action:'remove',id:g.id})" :title="'移除分组，角色返回未分组'">移除分组</button></div></div><div class="membership-head"><h3>角色分组与排序</h3><input aria-label="搜索分组角色" placeholder="搜索角色 / 区服" v-model="search"></div><div class="memberships"><div class="member-row" v-for="r in filtered" :key="r.key"><span><strong>{{r.name}}</strong><small>{{r.server}}</small></span><div class="sort-actions"><button :aria-label="'上移 '+r.name" :disabled="!neighbor(r,-1)" @click="moveRole(r,-1)">↑</button><button :aria-label="'下移 '+r.name" :disabled="!neighbor(r,1)" @click="moveRole(r,1)">↓</button></div><select :aria-label="r.name+'所在分组'" :value="r.group_id||''" @change="emit('action',{action:'assign',role:r.key,id:$event.target.value})"><option v-for="g in groups" :key="g.id" :value="g.id">{{g.name}}</option></select><button class="archive-remove" :aria-label="'移除档案 '+r.name" title="从日常清单移除并停止提醒，记录保留，可随时恢复" @click="emit('action',{action:'hide_role',role:r.key})">移除档案</button></div><p v-if="!filtered.length">没有匹配的角色</p></div><details v-if="archivedRoles.length" class="removed-archives"><summary>已移除档案 · {{archivedRoles.length}}</summary><p>记录仍保存在本地；读取运行窗口不会自动恢复到列表。</p><div v-for="r in archivedRoles" :key="r.key"><span>{{r.name}} <small>{{r.server}}</small></span><button :aria-label="'恢复档案 '+r.name" @click="emit('action',{action:'restore_role',role:r.key})">恢复档案</button></div></details></section></template>
<style scoped>
.group-editor{border:1px solid #dfd3bf;border-radius:9px;background:#fffcf6;padding:20px;margin-bottom:22px;color:#3b413b}.editor-head,.group-create,.membership-head{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.editor-head{margin-bottom:18px}h2{font-size:18px;margin:0 0 6px}h3{font-size:13px;font-weight:500;margin:0}p,small{font-size:11px;color:#998a74;margin:0;line-height:1.8}.group-create{justify-content:flex-start}button,input,select{font:inherit;font-size:12px;border:1px solid #dfd3bf;border-radius:6px;padding:8px 10px;background:#fffcf6;color:inherit;min-width:0}button{cursor:pointer}button:disabled{opacity:.4}input{max-width:100%}.group-names{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.group-names>div{display:flex;gap:5px}.group-names input{width:125px}.group-names button{font-size:11px;color:#9d8061}.membership-head{margin:20px 0 10px}.memberships{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:8px;max-height:310px;overflow:auto}.memberships .member-row{display:flex;align-items:center;justify-content:space-between;gap:15px;border-top:1px solid #eee7da;padding:10px 0}.memberships strong{display:block;font-size:12px;font-weight:500}.memberships small{display:block}.memberships select{width:115px}.memberships .member-row>span{min-width:0;overflow-wrap:anywhere}
.sort-actions{display:flex;gap:3px;margin-left:auto}.sort-actions button{padding:5px 8px}.memberships{grid-template-columns:repeat(auto-fill,minmax(290px,1fr))}.memberships .member-row{gap:8px}
.archive-remove{font-size:11px;white-space:nowrap;color:#9b6753}.memberships{grid-template-columns:repeat(auto-fill,minmax(350px,1fr))}.removed-archives{margin-top:20px;padding-top:12px;border-top:1px solid #e4dacb}.removed-archives summary{cursor:pointer;font-size:12px;color:#85725a}.removed-archives>div{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 0;font-size:12px}.removed-archives small{margin-left:8px}@media(max-width:650px){.memberships{grid-template-columns:1fr}.member-row{flex-wrap:wrap}}
</style>
